def solve(inputs: dict) -> float:
    M = inputs['M']
    power = inputs['power']
    mod = inputs['mod']

    # Matrix multiplication helper
    def matrix_mult(A, B, m):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % m
        return C

    # Matrix exponentiation using binary exponentiation
    def matrix_pow(M, p, m):
        n = len(M)
        # Start with identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]

        while p > 0:
            if p % 2 == 1:
                result = matrix_mult(result, base, m)
            base = matrix_mult(base, base, m)
            p //= 2

        return result

    result = matrix_pow(M, power, mod)

    # Sum all entries
    total = sum(sum(row) for row in result)
    return float(total)

